INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000065','sach-1','Những ngày chậm rãi','An Nhiên','Một lời nhắc dịu dàng để dừng lại, quan sát những điều nhỏ và tìm lại nhịp sống của riêng mình. Những tản văn về thành phố, căn bếp và các cuộc gặp bất chợt. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',128000,13,true,'00000000-0000-0000-0000-000000000001',1);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000066','sach-2','Phía bên kia mùa hạ','Lâm Vũ','Câu chuyện về tình bạn, những chuyến đi và một mùa hạ không thể quay lại. Một cuốn tiểu thuyết mẫu dành cho những buổi chiều nhiều nắng. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',159000,14,true,'00000000-0000-0000-0000-000000000001',2);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000067','sach-3','Thành phố trong trang giấy','Hà Mi','Đi qua những góc phố quen bằng một ánh nhìn mới. Tuyển tập truyện ngắn mẫu về ký ức và những người bình thường. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',145000,15,true,'00000000-0000-0000-0000-000000000001',3);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000068','sach-4','Một việc mỗi ngày','Minh An','Bắt đầu nhỏ, duy trì đều. Những bài thực hành ngắn giúp xây dựng thói quen học tập và làm việc có chủ đích. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',119000,16,true,'00000000-0000-0000-0000-000000000002',4);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000069','sach-5','Khoảng lặng cần thiết','Thanh Lam','Tìm sự tập trung giữa một ngày bận rộn. Các gợi ý thực hành về nghỉ ngơi, chú ý và sắp xếp ưu tiên. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',139000,17,true,'00000000-0000-0000-0000-000000000002',5);
INSERT INTO books VALUES ('00000000-0000-0000-0000-00000000006a','sach-6','Học cách bắt đầu','Gia Huy','Từ ý tưởng đầu tiên đến hành động nhỏ có thể thực hiện ngay. Một cuốn sách mẫu cho người đang tìm hướng đi. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',99000,18,true,'00000000-0000-0000-0000-000000000002',6);
INSERT INTO books VALUES ('00000000-0000-0000-0000-00000000006b','sach-7','Tư duy hướng đối tượng','Trạm Công Nghệ','Khám phá đóng gói, trừu tượng, kế thừa và đa hình qua ví dụ Java. Dành cho người muốn hiểu cách tổ chức chương trình dễ thay đổi. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',249000,12,true,'00000000-0000-0000-0000-000000000003',7);
INSERT INTO books VALUES ('00000000-0000-0000-0000-00000000006c','sach-8','Kiến trúc phần mềm dễ hiểu','Trần Khôi','Từ layered architecture đến modular monolith: cách chia trách nhiệm, quản lý phụ thuộc và lựa chọn kiến trúc phù hợp với bài toán. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',289000,13,true,'00000000-0000-0000-0000-000000000003',8);
INSERT INTO books VALUES ('00000000-0000-0000-0000-00000000006d','sach-9','Java từ những điều cơ bản','Ngọc Anh','Một hành trình thực hành với cú pháp Java, collection, exception và kiểm thử. Nội dung và tác giả là dữ liệu minh họa cho demo. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',219000,14,true,'00000000-0000-0000-0000-000000000003',9);
INSERT INTO books VALUES ('00000000-0000-0000-0000-00000000006e','sach-10','Màu của những điều nhỏ','Mai Chi','Ghi chép về màu sắc, bố cục và cảm hứng trong đời sống thường ngày. Một lời mời quan sát thế giới bằng con mắt tò mò. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',179000,15,true,'00000000-0000-0000-0000-000000000004',10);
INSERT INTO books VALUES ('00000000-0000-0000-0000-00000000006f','sach-11','Nhìn bằng đôi mắt mới','Phương Linh','Những bài tập sáng tạo ngắn về hình khối và câu chuyện thị giác. Dữ liệu sách mẫu được tạo riêng cho Trạm Sách. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',189000,16,true,'00000000-0000-0000-0000-000000000004',11);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000070','sach-12','Nét vẽ bên cửa sổ','Đan Thanh','Tìm cảm hứng từ một chiếc lá, khung cửa và ánh sáng buổi sáng. Cuốn sổ ý tưởng dành cho những người thích vẽ. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',169000,17,true,'00000000-0000-0000-0000-000000000004',12);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000071','sach-13','Cửa hàng của ngày mai','Vũ Minh','Tìm hiểu trải nghiệm khách hàng, vận hành và cách xây dựng một cửa hàng nhỏ bền vững. Các tình huống kinh doanh được hư cấu. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',199000,18,true,'00000000-0000-0000-0000-000000000005',13);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000072','sach-14','Hiểu khách hàng của bạn','Bảo Nguyên','Bắt đầu bằng việc lắng nghe. Một tập hợp bài tập mẫu về quan sát hành vi và cải thiện dịch vụ. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',189000,12,true,'00000000-0000-0000-0000-000000000005',14);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000073','sach-15','Làm việc có hệ thống','Anh Khoa','Biến công việc lặp lại thành quy trình rõ ràng, đo lường được và dễ bàn giao. Ví dụ thực hành cho nhóm nhỏ. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',159000,13,true,'00000000-0000-0000-0000-000000000005',15);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000074','sach-16','Căn bếp mùa nắng','Hương Giang','Những câu chuyện quanh bàn ăn và các ý tưởng cho bữa cơm giản dị. Hình bìa và nội dung là minh họa của dự án. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',149000,14,true,'00000000-0000-0000-0000-000000000006',16);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000075','sach-17','Trồng một góc xanh','Diệp Anh','Gợi ý tạo một góc xanh cho không gian nhỏ và ghi lại niềm vui chăm cây mỗi ngày. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',129000,15,true,'00000000-0000-0000-0000-000000000006',17);
INSERT INTO books VALUES ('00000000-0000-0000-0000-000000000076','sach-18','Đi để trở về','Nam Phong','Những ghi chép hư cấu về các chuyến đi ngắn, những con đường vắng và cảm giác trở về nhà. Đây là sản phẩm mẫu, không phải sách đang được chào bán thực tế.',159000,16,true,'00000000-0000-0000-0000-000000000006',18);
